int parse_csv_line(const char *line, char fields[][MAX_FIELD_LEN], int max_fields) {
    int field_count = 0;
    char *token = strtok(line, ",");

    if (!token) return 0; // Empty line, no fields to parse

    while (token && field_count < max_fields - 1) {
        strcpy(fields[field_count], token);
        token = strtok(NULL, ",");
        field_count++;
    }

    if (token) { // If there are more fields than max_fields, discard the rest
        while (token) {
            token = strtok(NULL, ",");
        }
    }

    if (field_count >= max_fields) { // If we reached max_fields, return max_fields-1 as the actual number of fields
        return max_fields - 1;
    } else {
        return field_count; // Return the actual number of fields parsed
    }
}
